pageCss:
.hf-code{background:#f4f6fa;border:1px solid #c8d2e2;border-left:3px solid #0831d9;padding:8px 10px;margin:0 0 12px;overflow-x:auto;font-size:9pt;line-height:1.5}
.hf-code code{white-space:pre}
.hf-demo{border:1px solid #9aa7ba;background:#f6f8fb;margin:14px 0 16px;box-shadow:inset 1px 1px 0 #fff}
.hf-bar{background:#e3e9f2;border-bottom:1px solid #c8d2e2;padding:5px 8px;display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap}
.hf-filters{display:inline-flex;gap:4px;flex-wrap:wrap}
.hf-filters button{font:inherit;font-size:8pt;padding:2px 8px;border:1px solid #a9b4c6;background:linear-gradient(180deg,#fff,#e6eaf1);border-radius:3px;cursor:pointer;color:#33415c}
.hf-filters button.on{background:linear-gradient(180deg,#cfe0fb,#a8c6f4);border-color:#5f86c8;color:#12305e;font-weight:bold}
.hf-count{font-size:8.5pt;color:#5c6779}
.hf-scroll{overflow-x:auto;background:#fff}
.hf-table{border-collapse:collapse;font-size:8.5pt;width:100%;min-width:560px}
.hf-table th{text-align:left;background:#e3e9f2;border:1px solid #c8d2e2;padding:4px 7px;font-family:var(--font-caption);color:#33415c;position:sticky;top:0}
.hf-table td{border:1px solid #d8dfeb;padding:4px 7px;vertical-align:top;line-height:1.45}
.hf-table tr:nth-child(even) td{background:#f8fafd}
.hf-table code{font-size:8pt;font-family:var(--font-mono)}
.hf-here td{background:#fdf6e0 !important;box-shadow:inset 3px 0 0 #e0a72c}
.hf-tag{display:inline-block;font-size:7.5pt;padding:0 5px;border-radius:8px;background:#dde5f2;color:#3d4d68;white-space:nowrap}
.hf-static{margin:0 0 12px}
.hf-ok{color:#1c6b32;font-weight:bold}
.hf-no{color:#a3261a;font-weight:bold}
.hf-case{padding:10px 12px;background:#fff;font-size:9pt;line-height:1.55}
.hf-case h4{font-family:var(--font-caption);color:#0831d9;font-size:10.5pt;margin:0 0 5px}
.hf-case pre{background:#f4f6fa;border:1px solid #c8d2e2;padding:7px 9px;margin:0 0 8px;overflow-x:auto;font-size:8.5pt}
.hf-case pre code{white-space:pre;font-family:var(--font-mono)}
.hf-case table{border-collapse:collapse;font-size:8.5pt;width:100%;margin:0 0 6px}
.hf-case th{text-align:left;background:#e3e9f2;border:1px solid #c8d2e2;padding:3px 7px;color:#33415c}
.hf-case td{border:1px solid #d8dfeb;padding:3px 7px;vertical-align:top}
.hf-cost{font-size:8.5pt;color:#5c6779;margin:0}
@media(max-width:620px){.hf-table{min-width:460px}}

