// /garage/hidden-flags — the inventory and the control picker.
//
// FLAGS is the full set of option definitions carrying `hidden: true` in the
// wrangler 4.125.0 bundle, read back with each flag's own describe string. The
// list is complete rather than curated: rows that matter here are marked, and
// the rest stay so the count is honest.
(function () {
  var FLAGS = [
    { f: "--experimental-new-config", a: "--x-new-config", g: "config", here: true,
      d: "[experimental] Use cloudflare.config.ts and wrangler.config.ts" },
    { f: "--experimental-cf-build-output", a: "--x-cf-build-output", g: "config", here: true,
      d: "[experimental] Emit a Build Output Specification directory under .cloudflare/output/ (requires --experimental-new-config)" },
    { f: "--experimental-auto-create", a: "--x-auto-create", g: "release", here: true,
      d: "Automatically provision draft bindings with new resources" },
    { f: "--experimental-provision", a: "", g: "release", here: true,
      d: "No description in the definition. Pinned off here alongside auto-create, because no deploy path on this account may create resources." },
    { f: "--max-versions", a: "", g: "release", here: true,
      d: "Maximum allowed versions to select. Defaults to 2, and its own comment says the limit is server side." },
    { f: "--experimental-deploy-helpers", a: "--x-deploy-helpers", g: "release", here: false,
      d: "Experimental: Gates refactored deploy/upload path" },
    { f: "--experimental-include-runtime", a: "--x-include-runtime", g: "types", here: false,
      d: "The path of the generated runtime types file" },
    { f: "--enable-containers", a: "", g: "containers", here: false,
      d: "Whether to build and enable containers during development" },
    { f: "--config-file", a: "-F", g: "containers", here: false,
      d: "Sets ssh -F: specify an alternative per-user ssh configuration file" },
    { f: "--identity-file", a: "-i", g: "containers", here: false,
      d: "Sets ssh -i: select a file from which the identity for public key authentication is read" },
    { f: "--escape-char", a: "", g: "containers", here: false,
      d: "Sets ssh -e: set the escape character for sessions with a pty" },
    { f: "--log-file", a: "", g: "containers", here: false,
      d: "Sets ssh -E: append debug logs to log_file instead of standard error" },
    { f: "--mac-spec", a: "", g: "containers", here: false,
      d: "Sets ssh -m: a comma separated list of message authentication code algorithms, in order of preference" },
    { f: "--delegate-c3", a: "--c3", g: "setup", here: false, d: "Delegate to Create Cloudflare CLI (C3)" },
    { f: "--install-wrangler", a: "", g: "setup", here: false, d: "Install Wrangler during project setup" },
    { f: "--completion-message", a: "", g: "setup", here: false,
      d: "Display a message with deployment details after wrangler setup is complete" },
    { f: "--node-compat", a: "", g: "legacy", here: false, d: "Enable Node.js compatibility" },
    { f: "--site-include", a: "", g: "legacy", here: false,
      d: "Workers Sites: gitignore style patterns; only matched items will be uploaded" },
    { f: "--site-exclude", a: "", g: "legacy", here: false,
      d: "Workers Sites: gitignore style patterns; matched items are skipped" },
  ];

  var GROUPS = [
    { k: "all", label: "all 19" },
    { k: "here", label: "touches this site" },
    { k: "release", label: "release path" },
    { k: "config", label: "config" },
    { k: "containers", label: "containers" },
    { k: "setup", label: "setup" },
    { k: "legacy", label: "legacy" },
    { k: "types", label: "types" },
  ];

  var CASES = [
    {
      k: "ignored",
      label: "the option may be silently ignored",
      title: "Run it three ways and compare the number",
      body: "An engine that ignores an option produces output identical to one that never received it, and the output still works. So do not ask whether it succeeded. Ask whether the thing the option claims to change actually changed, against a case where it could not have.",
      code: "compress(target)                 # no option\ncompress(target, opt: correct)   # the option, correct value\ncompress(target, opt: wrong)     # the option, useless value",
      table: [
        ["all three identical", "the option is being dropped"],
        ["correct one smaller, wrong one matches the first", "the option is honoured"],
        ["correct and wrong both differ from the first", "something reads the option and your model of it is off"],
      ],
      cost: "Cost: three local runs, no deploy. This is the control that separates node, workerd and bun on the same option.",
    },
    {
      k: "closed",
      label: "the schema may refuse unknown keys",
      title: "Send a key you invented, next to a request that fails anyway",
      body: "A closed schema validates the shape before it does any work, which makes it the cheapest oracle you will ever get. Pair the probe with a deliberately invalid input so nothing can execute even if the key is accepted.",
      code: 'send({ url: "not-a-url", definitely_not_a_key_xyz: 1 })\nsend({ url: "not-a-url", theKeyYouAreUnsure: 1 })',
      table: [
        ["first names your bogus key, second reports only the url error", "the key is accepted, and the schema is closed"],
        ["both report only the url error", "the schema is open, so acceptance proves nothing"],
        ["both name the bogus key", "your unsure key is being rejected too"],
      ],
      cost: "Cost: two rejected requests. Nothing renders, nothing is billed, and it answers acceptance completely.",
    },
    {
      k: "undocumented",
      label: "the docs skip the failure mode",
      title: "Read the exit code on a name that cannot exist",
      body: "Argument parsers either validate names or ignore them. One invented flag tells you which, and it tells you before you have trusted a real one.",
      code: "tool command --x-bogus-flag ; echo $?\ntool command --the-real-flag=false --dry-run ; echo $?",
      table: [
        ["1 then 0", "names are validated, so an accepted flag is a known flag"],
        ["0 then 0", "unknown names are ignored, and acceptance means nothing at all"],
        ["1 then 1", "the real flag is being rejected too, so check the spelling and the subcommand"],
      ],
      cost: "Cost: one exit code. Pair it with --dry-run so the second command performs no work.",
    },
    {
      k: "routing",
      label: "two paths both seem to work",
      title: "Compare the errors, rather than the successes",
      body: "When an old and a new URL spelling both respond, a success on either one proves nothing about which is live. The distinguishing signal lives in what each one says when it refuses, and an unauthenticated request is enough to get it.",
      code: "curl -s https://api/OLD-SPELLING/action   # unauthenticated\ncurl -s https://api/NEW-SPELLING/action   # unauthenticated",
      table: [
        ["both report an auth error", "both spellings route, so pick the one the feature's own page documents"],
        ["one reports could-not-route", "that spelling is dead and the choice is made for you"],
        ["one reports auth and the other 404s", "same conclusion, through a different status"],
      ],
      cost: "Cost: two unauthenticated requests. No credential, so this one is safe to run against somebody else's API.",
    },
  ];

  var filters = document.getElementById("hf-filters");
  var table = document.getElementById("hf-table");
  var count = document.getElementById("hf-count");
  var cases = document.getElementById("hf-cases");
  var caseBox = document.getElementById("hf-case");
  var active = "all";

  function matches(row) {
    if (active === "all") return true;
    if (active === "here") return row.here;
    return row.g === active;
  }

  function drawTable() {
    if (!table) return;
    table.textContent = "";
    var head = document.createElement("tr");
    ["flag", "alias", "group", "what it says it does"].forEach(function (h) {
      var th = document.createElement("th");
      th.textContent = h;
      head.appendChild(th);
    });
    table.appendChild(head);
    var shown = 0;
    FLAGS.forEach(function (row) {
      if (!matches(row)) return;
      shown++;
      var tr = document.createElement("tr");
      if (row.here) tr.className = "hf-here";
      var c1 = document.createElement("td");
      var code = document.createElement("code");
      code.textContent = row.f;
      c1.appendChild(code);
      var c2 = document.createElement("td");
      if (row.a) {
        var al = document.createElement("code");
        al.textContent = row.a;
        c2.appendChild(al);
      }
      var c3 = document.createElement("td");
      var tag = document.createElement("span");
      tag.className = "hf-tag";
      tag.textContent = row.g;
      c3.appendChild(tag);
      var c4 = document.createElement("td");
      c4.textContent = row.d;
      [c1, c2, c3, c4].forEach(function (c) { tr.appendChild(c); });
      table.appendChild(tr);
    });
    if (count) {
      count.textContent = shown === FLAGS.length
        ? shown + " hidden flags"
        : shown + " of " + FLAGS.length + " hidden flags";
    }
  }

  if (filters) {
    GROUPS.forEach(function (g) {
      var btn = document.createElement("button");
      btn.type = "button";
      btn.textContent = g.label;
      if (g.k === active) btn.className = "on";
      btn.addEventListener("click", function () {
        active = g.k;
        Array.prototype.forEach.call(filters.children, function (b) { b.classList.toggle("on", b === btn); });
        drawTable();
      });
      filters.appendChild(btn);
    });
  }

  function drawCase(c) {
    if (!caseBox) return;
    caseBox.textContent = "";
    var h = document.createElement("h4");
    h.textContent = c.title;
    var p = document.createElement("p");
    p.textContent = c.body;
    var pre = document.createElement("pre");
    var code = document.createElement("code");
    code.textContent = c.code;
    pre.appendChild(code);
    var tbl = document.createElement("table");
    var head = document.createElement("tr");
    ["what you see", "what it means"].forEach(function (t) {
      var th = document.createElement("th");
      th.textContent = t;
      head.appendChild(th);
    });
    tbl.appendChild(head);
    c.table.forEach(function (pair) {
      var tr = document.createElement("tr");
      pair.forEach(function (cell) {
        var td = document.createElement("td");
        td.textContent = cell;
        tr.appendChild(td);
      });
      tbl.appendChild(tr);
    });
    var cost = document.createElement("p");
    cost.className = "hf-cost";
    cost.textContent = c.cost;
    [h, p, pre, tbl, cost].forEach(function (n) { caseBox.appendChild(n); });
  }

  if (cases) {
    CASES.forEach(function (c, i) {
      var btn = document.createElement("button");
      btn.type = "button";
      btn.textContent = c.label;
      if (i === 0) btn.className = "on";
      btn.addEventListener("click", function () {
        Array.prototype.forEach.call(cases.children, function (b) { b.classList.toggle("on", b === btn); });
        drawCase(c);
      });
      cases.appendChild(btn);
    });
    drawCase(CASES[0]);
  }

  drawTable();
})();
